<script>
  // Maps a RAG confidence level to a CSS class name.
  function confidenceBadgeClass(confidence) {
    if (confidence === 'high') {
      return 'confidence-high';
    } else if (confidence === 'medium') {
      return 'confidence-medium';
    } else if (confidence === 'low') {
